pipeline.runs:
set +x
d=$(mktemp -d)
echo "$ ${{vars.python}} -m venv $d"
${{vars.python}} -m venv "$d"
echo "$ $d/bin/pip list"
$d/bin/pip list | tee "$d/list.txt"
wd=/usr/share/python-wheels
for pkg in pip ; do
  set -- "$wd"/$pkg-*.whl
  [ $# -eq 1 ] || {
    echo "ERROR: found $# wheels in $wd matching $pkg-*.whl";
    exit 1;
  }
  [ -f "$1" ] || {
    echo "ERROR: $wd/$pkg-*.whl ('$1') was not a file"
    exit 1
  }
  # name is like pip-24.2-py3-none-any.whl. second token is version.
  wheel=${1}
  tmp=${wheel##*/}
  tmp=${tmp#*-}
  ver=${tmp%%-*}
  if ! grep -q "${pkg}[ ]\+${ver}$" "$d/list.txt"; then
      echo "FAIL: did not find '$pkg==$ver' in venv"
      echo "pip list had:"
      sed 's,^,>,' "$d/list.txt"
      exit 1
  fi
  echo "PASS: venv installed '$pkg==$ver'"
done

rm -Rf "$d"

python="${{vars.python}}"
d=$(mktemp -d)
cat > "$d/c_ext_check.c" <<'EOF'
#include <Python.h>
static PyObject *answer(PyObject *self, PyObject *args) { return PyLong_FromLong(42); }
static PyMethodDef methods[] = {{"answer", answer, METH_NOARGS, NULL}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "c_ext_check", NULL, 0, methods};
PyMODINIT_FUNC PyInit_c_ext_check(void) { return PyModuleDef_Init(&module); }
EOF
include=$("$python" -c 'import sysconfig; print(sysconfig.get_path("include"))')
ext=$("$python" -c 'import sysconfig; print(sysconfig.get_config_var("EXT_SUFFIX"))')
cc -shared -fPIC -I"$include" "$d/c_ext_check.c" -o "$d/c_ext_check$ext"
"$python" -c "import sys; sys.path.insert(0, sys.argv[1]); import c_ext_check; assert c_ext_check.answer() == 42; print('c_ext_check: built and imported')" "$d"
rm -rf "$d"

python="${{vars.python}}"
d=$(mktemp -d)
cat > "$d/c_ext_check.c" <<'EOF'
#include <Python.h>
static PyObject *answer(PyObject *self, PyObject *args) { return PyLong_FromLong(42); }
static PyMethodDef methods[] = {{"answer", answer, METH_NOARGS, NULL}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "c_ext_check", NULL, 0, methods};
PyMODINIT_FUNC PyInit_c_ext_check(void) { return PyModuleDef_Init(&module); }
EOF
include=$("$python" -c 'import sysconfig; print(sysconfig.get_path("include"))')
ext=$("$python" -c 'import sysconfig; print(sysconfig.get_config_var("EXT_SUFFIX"))')
cc -shared -fPIC -I"$include" "$d/c_ext_check.c" -o "$d/c_ext_check$ext"
"$python" -c "import sys; sys.path.insert(0, sys.argv[1]); import c_ext_check; assert c_ext_check.answer() == 42; print('c_ext_check: built and imported')" "$d"
rm -rf "$d"
